// Generated by Decentraland Studio. Do not edit: this copy is kept in sync with your editor version.
// The one screen layout every HUD in the scene shares, so prefabs and custom HUDs stack instead of overlapping
// on any screen, down to a phone's 1600x720 canvas minus the explorer's controls (about 1056x643).
// It holds two kinds of UI: the HUD, which stays on screen while the game plays (the four edge slots), and
// windows the player interacts with for a moment (the 'modal' slot): shop, recipe choice, dialog, results.
//
// addHudItem(slot, render, { order, open, close }) adds a panel and returns a function that removes it:
// - 'left' / 'right': columns stacked from the top, at most HUD_COLUMN_WIDTH wide. On a phone the right column
//   ends above the action buttons the scene declares, and the left column is drawn against the screen's left edge,
//   below the explorer's top-left buttons and above the joystick, in the space the explorer's chat opens over: only
//   glanceable, non-interactive info (score, lives, a status line) the game can live without while the chat is
//   open, and never for a game that needs the chat open; buttons and anything essential go right, top or in a
//   window. Both columns cut off what does not fit;
// - 'top': status and notifications at the top centre, at most HUD_COLUMN_WIDTH wide;
// - 'bottom': short hints and notices above the bottom centre, at most HUD_NOTICE_WIDTH wide, never interactive;
// - 'modal': a window, drawn only while its `open()` answers true, centred in the interactable area over the
//   game. With `close`, the whole screen behind it dims and a tap there calls close(). Its render draws the
//   window whenever it is called (open() alone decides when it shows), so the editor's mobile check can open it
//   to measure it; give the window's panel a uiTransform elementId so it is measured. While it is open the
//   phone's touch controls are hidden, because they are drawn over it. A modal with no open() never closes.
//   UiWindow from ./uiWindow is the ready-made window, and mountWindow places one here.
// Lower `order` sits closer to the screen edge. Nothing is placed in the bottom corners: on phones the
// joystick and the jump/E/F buttons are there. Every item needs an explicit width and height.
// hudSpace(slot) is the height a slot has on this device: size a list that grows during play to it (show at
// most that many rows), since the HUD is measured as it looks mid-game.
// render() returns an element and calls no hooks (it runs inside the layout); state lives in the component it returns.
//
// declareTouchButtons(buttons, { main }) says which native touch buttons the scene uses; on phones every other
// one is hidden (an unused button tells the player there is an action that does nothing). Each entry is an
// InputAction, or { action, icon } where icon is an image in the scene that replaces the button's generic
// E/F/1-4 glyph: actionIcon('chop') from ./actionIcons (pick-up, drop, chop, cook, wash, throw, use, serve,
// jump, interact, attack, talk), or your own white-on-transparent square PNG. `main` takes the large button.
//   declareTouchButtons([{ action: InputAction.IA_PRIMARY, icon: actionIcon('pick-up') },
//     { action: InputAction.IA_SECONDARY, icon: actionIcon('chop') }], { main: InputAction.IA_PRIMARY })
// Prefabs and scripts each declare their own and the layout shows the union (the first icon given for an
// action wins). Set the touch controls only through here: the layout writes TouchScreenControls itself, and
// restores this setup when a modal closes.
import ReactEcs, { InteractableArea, ReactEcsRenderer, UiEntity } from '@dcl/sdk/react-ecs'
import { engine, InputAction, Schemas, TouchScreenControls, type LastWriteWinElementSetComponentDefinition } from '@dcl/sdk/ecs'
import { isMobile } from '@dcl/sdk/platform'
import { UI_CANVAS } from './uiTheme'
import { PHONE_LEFT_COLUMN, PHONE_SCREEN, phoneShare } from './pure/phoneControls'

export type HudSlot = 'left' | 'top' | 'right' | 'bottom' | 'modal'
export const HUD_COLUMN_WIDTH = 340
export const HUD_GAP = 12
// clear of the phone's E/F/pointer buttons beside the bottom centre
export const HUD_NOTICE_WIDTH = 440
// clear of the explorer's own edge controls inside the interactable area
const HUD_MARGIN = 20
// a phone's interactable area, and where its middle third (the avatar, what the player acts on) begins and ends
const PHONE_AREA = { top: 32, height: 643, centreTop: 240, centreBottom: 480 }
const DESKTOP_AREA = { height: 1080, centreTop: 360 }
const WINDOW_DIM = { r: 0, g: 0, b: 0, a: 0.6 }

// the native buttons TouchScreenControls can show or hide (movement is the joystick)
const TOUCH_BUTTONS = [InputAction.IA_POINTER, InputAction.IA_PRIMARY, InputAction.IA_SECONDARY, InputAction.IA_JUMP,
  InputAction.IA_ACTION_3, InputAction.IA_ACTION_4, InputAction.IA_ACTION_5, InputAction.IA_ACTION_6]

// The editor's mobile check writes this on the root entity to open one modal (by its index) and measure it,
// or ALL_CLOSED to measure the HUD as it looks during play.
const ALL_CLOSED = -2
const HudPreview = (engine.getComponentOrNull('editor::HudPreview') ?? engine.defineComponent('editor::HudPreview', {
  modal: Schemas.Int
})) as LastWriteWinElementSetComponentDefinition<{ modal: number }>

interface HudItem {
  id: number
  slot: HudSlot
  order: number
  render(): ReactEcs.JSX.Element | null
  open?(): boolean
  close?(): void
}

/** A native touch button the scene uses, with the image (a path in the scene) drawn on it instead of its glyph. */
export interface TouchButton { action: InputAction; icon?: string }

interface TouchDeclaration { id: number; buttons: TouchButton[]; main?: InputAction }

interface HudLayoutState {
  items: HudItem[]
  touch: TouchDeclaration[]
  nextId: number
  mounted: boolean
  // what was last written to TouchScreenControls, so it is written only when it changes
  applied: string
}

const KEY = '__dclHudLayout_v2'
const store = globalThis as unknown as Record<string, HudLayoutState | undefined>

function layout(): HudLayoutState {
  store[KEY] ??= { items: [], touch: [], nextId: 1, mounted: false, applied: '' }
  return store[KEY]
}

function mount(state: HudLayoutState): void {
  if (state.mounted) return
  state.mounted = true
  ReactEcsRenderer.addUiRenderer(engine.addEntity(), HudLayout, UI_CANVAS)
  ReactEcsRenderer.addUiRenderer(engine.addEntity(), PhoneLeftColumn, { ...UI_CANVAS, screenInset: 'none' })
  ReactEcsRenderer.addUiRenderer(engine.addEntity(), WindowLayer, { ...UI_CANVAS, screenInset: 'none', zIndex: 10 })
  engine.addSystem(syncTouchControls)
}

/** Movement controls as the player's device calls them. */
export function controlsHint(): string {
  return isMobile() ? 'Joystick to move · Jump button to jump' : 'WASD move · Space jump'
}

export function addHudItem(slot: HudSlot, render: () => ReactEcs.JSX.Element | null,
  options: { order?: number; open?: () => boolean; close?: () => void } = {}): () => void {
  const state = layout()
  const item: HudItem = { id: state.nextId++, slot, order: options.order ?? 0, render, open: options.open, close: options.close }
  state.items.push(item)
  mount(state)
  return () => { state.items = state.items.filter((other) => other !== item) }
}

/** The native touch buttons this script uses; on phones the ones no script declares are hidden. */
export function declareTouchButtons(buttons: Array<InputAction | TouchButton>, options: { main?: InputAction } = {}): () => void {
  const state = layout()
  const declaration: TouchDeclaration = { id: state.nextId++, main: options.main,
    buttons: buttons.map((button) => typeof button === 'object' ? button : { action: button }) }
  state.touch.push(declaration)
  mount(state)
  return () => { state.touch = state.touch.filter((other) => other !== declaration) }
}

function previewedModal(): number {
  return HudPreview.getOrNull(engine.RootEntity)?.modal ?? -1
}

function modalOpen(item: HudItem, index: number): boolean {
  const previewed = previewedModal()
  if (previewed === ALL_CLOSED) return item.open === undefined
  return index === previewed || item.open?.() !== false
}

function declaredButtons(): number {
  return new Set(layout().touch.flatMap((declaration) => declaration.buttons.map((button) => button.action))).size
}

// How far above the interactable area's bottom a phone's action buttons reach: the large button alone, up to two
// arc buttons beside it, or the full arc (the editor's mobile check places them the same way).
function actionButtonsReach(): number {
  const shown = declaredButtons() || TOUCH_BUTTONS.length
  return (shown === 1 ? 156 : shown <= 3 ? 236 : 281) + HUD_GAP
}

/** The height a HUD slot's stack has on this device, clear of the touch controls and the screen centre. */
export function hudSpace(slot: Exclude<HudSlot, 'modal'>): number {
  if (!isMobile()) return slot === 'left' || slot === 'right' ? DESKTOP_AREA.height - 2 * HUD_MARGIN : DESKTOP_AREA.centreTop - 2 * HUD_MARGIN
  if (slot === 'right') return PHONE_AREA.height - HUD_MARGIN - actionButtonsReach()
  if (slot === 'left') return PHONE_LEFT_COLUMN.bottom - PHONE_LEFT_COLUMN.top
  if (slot === 'top') return PHONE_AREA.centreTop - PHONE_AREA.top - HUD_MARGIN
  return PHONE_AREA.top + PHONE_AREA.height - HUD_MARGIN - PHONE_AREA.centreBottom
}

function syncTouchControls(): void {
  const state = layout()
  const hideAll = itemsIn('modal').some((item, index) => item.open !== undefined && modalOpen(item, index))
  const buttons = state.touch.flatMap((declaration) => declaration.buttons)
  const used = new Set(buttons.map((button) => button.action))
  const icons = new Map<InputAction, string>()
  for (const button of buttons) if (button.icon !== undefined && !icons.has(button.action)) icons.set(button.action, button.icon)
  const main = state.touch.find((declaration) => declaration.main !== undefined)?.main
  // nothing declared and no dialog: the explorer's defaults stand
  const next = hideAll || used.size > 0 ? JSON.stringify({ hideAll, used: [...used].sort(), main, icons: [...icons].sort() }) : ''
  if (next === state.applied) return
  state.applied = next
  TouchScreenControls.createOrReplace(engine.RootEntity, {
    touchInputs: TOUCH_BUTTONS.map((inputAction) => ({ inputAction, hide: hideAll || (used.size > 0 && !used.has(inputAction)),
      ...iconField(icons.get(inputAction)) })),
    mainAction: main,
    hideJoystick: hideAll,
    hideCrosshair: false
  })
}

function iconField(src: string | undefined) {
  return src === undefined ? {} : { icon: { tex: { $case: 'texture' as const, texture: { src } } } }
}

function itemsIn(slot: HudSlot): HudItem[] {
  return layout().items.filter((item) => item.slot === slot).sort((a, b) => a.order - b.order || a.id - b.id)
}

// An item that draws nothing takes no space; the SDK has no flex gap, so a fixed spacer keeps the rest apart.
// Each item is wrapped in a box with an elementId (hud:<slot>:<index>), so the editor can measure it.
function drawn(slot: Exclude<HudSlot, 'modal'>): ReactEcs.JSX.Element[] {
  const out: ReactEcs.JSX.Element[] = []
  itemsIn(slot).forEach((item, index) => {
    const element = item.render()
    if (element === null) return
    if (out.length > 0) out.push(<UiEntity key={`gap-${item.id}`} uiTransform={{ width: 1, height: HUD_GAP, flexShrink: 0, pointerFilter: 'none' }} />)
    out.push(<UiEntity key={item.id} uiTransform={{ elementId: `hud:${slot}:${index}`, flexShrink: 0, pointerFilter: 'none' }}>
      {element}
    </UiEntity>)
  })
  return out
}

type Offset = number | `${number}%`

function Stack(props: { slot: Exclude<HudSlot, 'modal'>; align: 'flex-start' | 'center' | 'flex-end'; side: { left?: Offset; right?: Offset }; top?: Offset; bottom?: Offset }) {
  const items = drawn(props.slot)
  if (items.length === 0) return null
  const fromBottom = props.slot === 'bottom'
  const vertical = fromBottom ? { bottom: HUD_MARGIN } : { top: props.top ?? HUD_MARGIN, ...(props.bottom === undefined ? {} : { bottom: props.bottom }) }
  const size = props.bottom === undefined ? { height: '100%' as const } : { overflow: 'hidden' as const }
  return <UiEntity uiTransform={{ positionType: 'absolute', position: { ...props.side, ...vertical },
    width: props.align === 'center' ? '100%' : HUD_COLUMN_WIDTH, ...size, flexDirection: fromBottom ? 'column-reverse' : 'column',
    alignItems: props.align, justifyContent: 'flex-start', pointerFilter: 'none' }}>
    {items}
  </UiEntity>
}

function HudLayout() {
  const phone = isMobile()
  return <UiEntity uiTransform={{ positionType: 'absolute', width: '100%', height: '100%', pointerFilter: 'none' }}>
    <Stack slot="top" align="center" side={{ left: 0 }} />
    <Stack slot="bottom" align="center" side={{ left: 0 }} />
    {phone ? null : <Stack slot="left" align="flex-start" side={{ left: HUD_MARGIN }} />}
    <Stack slot="right" align="flex-end" side={{ right: HUD_MARGIN }} bottom={phone ? actionButtonsReach() : undefined} />
    {/* how many modals the mobile check can open, one by one */}
    <UiEntity uiTransform={{ elementId: `hud:modals:${itemsIn('modal').length}`, positionType: 'absolute', width: 1, height: 1, pointerFilter: 'none' }} />
  </UiEntity>
}

// The phone's interactable area starts right of the explorer's chat column, about a quarter across: drawn there the
// left column would float beside the top centre. It is placed on the whole screen instead, in shares of it, so it
// follows the explorer's controls on any phone.
function PhoneLeftColumn() {
  if (!isMobile()) return null
  return <Stack slot="left" align="flex-start" side={{ left: phoneShare(PHONE_LEFT_COLUMN.left, 'width') }}
    top={phoneShare(PHONE_LEFT_COLUMN.top, 'height')} bottom={phoneShare(PHONE_SCREEN.height - PHONE_LEFT_COLUMN.bottom, 'height')} />
}

// Windows draw over the whole screen so a backdrop can dim all of it; the window itself stays in the interactable area.
function WindowLayer() {
  const out: ReactEcs.JSX.Element[] = []
  itemsIn('modal').forEach((item, index) => {
    if (!modalOpen(item, index)) return
    const element = item.render()
    if (element === null) return
    const close = item.close
    out.push(<UiEntity key={item.id} uiTransform={{ elementId: `hud:modal:${index}`, positionType: 'absolute', width: '100%', height: '100%',
      pointerFilter: close === undefined ? 'none' : 'block' }} uiBackground={close === undefined ? undefined : { color: WINDOW_DIM }}
      onMouseDown={close === undefined ? undefined : () => close()}>
      <InteractableArea uiTransform={{ alignItems: 'center', justifyContent: 'center', pointerFilter: 'none' }}>{element}</InteractableArea>
    </UiEntity>)
  })
  return <UiEntity uiTransform={{ positionType: 'absolute', width: '100%', height: '100%', pointerFilter: 'none' }}>{out}</UiEntity>
}
